-- Kenya Tech Job Market Analysis - Database Schema
-- This schema represents the 'job_postings' table generated by the Pandas to_sql load process.

CREATE TABLE IF NOT EXISTS job_postings (
    job_id TEXT PRIMARY KEY,
    job_title TEXT,
    company TEXT,
    location TEXT,
    job_type TEXT,
    experience_level TEXT,
    skills TEXT,
    remote_status TEXT,
    date_posted DATETIME,
    source TEXT,
    captured_at DATETIME,
    req_python BOOLEAN,
    req_sql BOOLEAN,
    req_javascript BOOLEAN,
    req_cloud BOOLEAN,
    is_entry_level BOOLEAN
);